WITH recent_ship_sales AS ( SELECT cc.cc_name AS call_center_name, cs.cs_ship_mode_sk AS ship_mode, cs.cs_net_profit, cs.cs_net_paid_inc_tax, d.d_year, d.d_month_seq FROM catalog_sales cs JOIN call_center cc ON cs.cs_call_center_sk = cc.cc_call_center_sk JOIN date_dim d ON cs.cs_ship_date_sk = d.d_date_sk WHERE d.d_year = (SELECT MAX(d_year) FROM date_dim) ) SELECT call_center_name, ship_mode, d_month_seq, SUM(cs_net_profit) AS total_profit, SUM(cs_net_paid_inc_tax) AS total_paid, RANK() OVER (PARTITION BY call_center_name ORDER BY SUM(cs_net_profit) DESC) AS profit_rank FROM recent_ship_sales GROUP BY call_center_name, ship_mode, d_month_seq ORDER BY call_center_name, profit_rank
